#include "risk/analytics.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
#include <numeric>
#include <stdexcept>
namespace risk {
static double na(){return std::numeric_limits<double>::quiet_NaN();}
static double mean(const std::vector<double>& v){return v.empty()?na():std::accumulate(v.begin(),v.end(),0.0)/v.size();}
static double variance(const std::vector<double>& v){if(v.size()<2)return na();double m=mean(v),s=0;for(double x:v)s+=(x-m)*(x-m);return s/(v.size()-1);}
Analysis analyze(const std::vector<Observation>& a,const Config& c){if(a.empty()||!std::isfinite(c.periods)||c.periods<=0||!std::isfinite(c.rf)||c.rf<=-1||!(c.confidence>0&&c.confidence<1)||c.window<2)throw std::invalid_argument("Invalid configuration or empty data");Analysis z;auto& m=z.metrics;double peak=a.front().price;for(size_t i=0;i<a.size();++i){if(!std::isfinite(a[i].price)||a[i].price<=0||(i&&a[i].day<=a[i-1].day))throw std::invalid_argument("Invalid observation order or price");peak=std::max(peak,a[i].price);z.drawdown.push_back(1-a[i].price/peak);z.rolling.push_back(na());if(i){double l=std::log(a[i].price)-std::log(a[i-1].price);double r=(a[i].price-a[i-1].price)/a[i-1].price;if(!std::isfinite(r))throw std::overflow_error("Return overflow");z.logs.push_back(l);z.returns.push_back(r);if(i>=c.window){std::vector<double> w(z.returns.end()-c.window,z.returns.end());z.rolling.back()=std::sqrt(variance(w)*c.periods);}}}auto& r=z.returns;double n=r.size(),mu=mean(r),v=variance(r),sd=std::sqrt(v),g=std::log(a.back().price)-std::log(a.front().price),rf=std::expm1(std::log1p(c.rf)/c.periods),down=0;for(double x:r)down+=std::pow(std::min(0.0,x-rf),2);down=n?std::sqrt(down/n):na();m={{"mean_simple",mu},{"mean_log",mean(z.logs)},{"geometric_return",n?std::expm1(g/n):na()},{"sample_variance",v},{"volatility",sd},{"annual_volatility",sd*std::sqrt(c.periods)},{"annual_arithmetic",mu*c.periods},{"annual_geometric",n?std::expm1(g*c.periods/n):na()},{"calendar_cagr",n?std::expm1(g*365.2425/(a.back().day-a.front().day)):na()},{"sharpe",sd>0?(mu-rf)*std::sqrt(c.periods)/sd:na()},{"sortino",down>0?(mu-rf)*std::sqrt(c.periods)/down:na()},{"downside_deviation",down},{"max_drawdown",*std::max_element(z.drawdown.begin(),z.drawdown.end())},{"var",na()},{"es",na()}};if(n){std::vector<double> loss;for(double x:r)loss.push_back(-x);std::sort(loss.begin(),loss.end());size_t k=static_cast<size_t>(std::ceil(c.confidence*n))-1;m["var"]=loss[k];double mass=(1-c.confidence)*n,remaining=mass,sum=0;for(auto it=loss.rbegin();it!=loss.rend()&&remaining>0;++it){double w=std::min(1.0,remaining);sum+=w* *it;remaining-=w;}m["es"]=sum/mass;}for(auto& kv:m)if(!std::isfinite(kv.second))kv.second=na();return z;}
}
